//! Oracle vectors: the case mapping of every code point in all eight `MB_CASE_*` modes, and the
//! `Cased` / `Case_Ignorable` properties of every code point, as PHP 8.5.13's mbstring has them.
//!
//! `tests/vectors/case_map.json` is generated by `tests/vectors/case_map.gen.php` in the PHP
//! oracle (`research/php-oracle`). Regenerate from the repository root with
//!
//! ```text
//! docker run --rm -i twig-oracle:3.31.1 php < crates/twig-unicode/tests/vectors/case_map.gen.php \
//!     > crates/twig-unicode/tests/vectors/case_map.json
//! ```

use std::collections::HashMap;

use serde::Deserialize;
use twig_unicode::case::{
    to_fold_full, to_fold_simple, to_lower_full, to_lower_simple, to_title_full, to_title_simple,
    to_upper_full, to_upper_simple,
};
use twig_unicode::props::{is_case_ignorable, is_cased};
use twig_unicode::{CaseMode, convert_case, mb_strtolower, mb_strtoupper};

#[derive(Deserialize)]
struct CaseMap {
    php_version: String,
    anomalies: Vec<String>,
    upper: Vec<(u32, Vec<u32>)>,
    lower: Vec<(u32, Vec<u32>)>,
    title: Vec<(u32, Vec<u32>)>,
    fold: Vec<(u32, Vec<u32>)>,
    upper_simple: Vec<(u32, Vec<u32>)>,
    lower_simple: Vec<(u32, Vec<u32>)>,
    title_simple: Vec<(u32, Vec<u32>)>,
    fold_simple: Vec<(u32, Vec<u32>)>,
    cased: Vec<(u32, u32)>,
    case_ignorable: Vec<(u32, u32)>,
}

fn load() -> CaseMap {
    let map: CaseMap = serde_json::from_str(include_str!("vectors/case_map.json")).unwrap();
    assert_eq!(map.php_version, "8.5.13");
    assert!(map.anomalies.is_empty(), "{:?}", map.anomalies);
    map
}

fn code_points() -> impl Iterator<Item = u32> {
    (0..=0x10_FFFFu32).filter(|cp| !(0xD800..=0xDFFF).contains(cp))
}

fn decode(bytes: &[u8]) -> Vec<u32> {
    std::str::from_utf8(bytes)
        .unwrap()
        .chars()
        .map(u32::from)
        .collect()
}

fn encode(cp: u32) -> String {
    char::from_u32(cp).unwrap().to_string()
}

impl CaseMap {
    fn entries(&self, mode: CaseMode) -> &[(u32, Vec<u32>)] {
        match mode {
            CaseMode::Upper => &self.upper,
            CaseMode::Lower => &self.lower,
            CaseMode::Title => &self.title,
            CaseMode::Fold => &self.fold,
            CaseMode::UpperSimple => &self.upper_simple,
            CaseMode::LowerSimple => &self.lower_simple,
            CaseMode::TitleSimple => &self.title_simple,
            CaseMode::FoldSimple => &self.fold_simple,
        }
    }
}

/// The code-point level mapping that a one-character string gets in `mode`.
fn map_code_point(mode: CaseMode, cp: u32) -> Vec<u32> {
    match mode {
        CaseMode::Upper => to_upper_full(cp).to_vec(),
        CaseMode::Lower => to_lower_full(cp).to_vec(),
        CaseMode::Title => to_title_full(cp).to_vec(),
        CaseMode::Fold => to_fold_full(cp).to_vec(),
        CaseMode::UpperSimple => vec![to_upper_simple(cp)],
        CaseMode::LowerSimple => vec![to_lower_simple(cp)],
        CaseMode::TitleSimple => vec![to_title_simple(cp)],
        CaseMode::FoldSimple => vec![to_fold_simple(cp)],
    }
}

#[test]
fn every_code_point_maps_like_php() {
    let map = load();
    for mode in CaseMode::ALL {
        let expected: HashMap<u32, &[u32]> = map
            .entries(mode)
            .iter()
            .map(|(cp, to)| (*cp, to.as_slice()))
            .collect();
        assert_eq!(
            expected.len(),
            map.entries(mode).len(),
            "duplicate entries for {mode:?}"
        );
        let mut changed = 0;
        for cp in code_points() {
            let want = expected
                .get(&cp)
                .copied()
                .unwrap_or(std::slice::from_ref(&cp));
            assert_eq!(map_code_point(mode, cp), want, "{mode:?} U+{cp:04X}");
            // The string conversion of every changed code point, and of a sample of the others.
            if expected.contains_key(&cp) || cp % 61 == 0 {
                let got = convert_case(mode, encode(cp).as_bytes());
                assert_eq!(decode(&got), want, "{mode:?} U+{cp:04X} as a string");
                changed += usize::from(expected.contains_key(&cp));
            }
        }
        assert_eq!(
            changed,
            expected.len(),
            "{mode:?}: mapped code point outside U+0000..U+10FFFF"
        );
    }
}

#[test]
fn strtoupper_and_strtolower_are_the_full_mappings() {
    let map = load();
    for (cp, want) in &map.upper {
        assert_eq!(
            decode(&mb_strtoupper(encode(*cp).as_bytes())),
            *want,
            "U+{cp:04X}"
        );
    }
    for (cp, want) in &map.lower {
        assert_eq!(
            decode(&mb_strtolower(encode(*cp).as_bytes())),
            *want,
            "U+{cp:04X}"
        );
    }
}

#[test]
fn cased_and_case_ignorable_match_php_for_every_code_point() {
    let map = load();
    for (name, ranges, lookup) in [
        ("Cased", &map.cased, is_cased as fn(u32) -> bool),
        ("Case_Ignorable", &map.case_ignorable, is_case_ignorable),
    ] {
        let mut ranges = ranges.iter().peekable();
        for cp in code_points() {
            while ranges.next_if(|(_, last)| *last < cp).is_some() {}
            let want = ranges.peek().is_some_and(|(first, _)| *first <= cp);
            assert_eq!(lookup(cp), want, "{name} U+{cp:04X}");
        }
    }
}
